Here’s a **simple C++ program** showing **multilevel inheritance** — `student → marks → result`:  

```cpp
#include <iostream>
using namespace std;

class student {
protected:
    int roll;
    string name;
public:
    void getdata_student() {
        cout << "Enter name: ";
        cin >> name;
        cout << "Enter roll number: ";
        cin >> roll;
    }
    void display_student() {
        cout << "Name: " << name << endl;
        cout << "Roll No: " << roll << endl;
    }
};

class marks : public student {
protected:
    int m1, m2, m3;
public:
    void getdata_marks() {
        cout << "Enter marks of 3 subjects: ";
        cin >> m1 >> m2 >> m3;
    }
    void display_marks() {
        cout << "Marks: " << m1 << ", " << m2 << ", " << m3 << endl;
    }
};

class result : public marks {
    int total;
    float avg;
public:
    void calculate() {
        total = m1 + m2 + m3;
        avg = total / 3.0;
    }
    void display_result() {
        display_student();
        display_marks();
        cout << "Total: " << total << endl;
        cout << "Average: " << avg << endl;
    }
};

int main() {
    result r;
    r.getdata_student();
    r.getdata_marks();
    r.calculate();
    r.display_result();
    return 0;
}
```

✅ **Explanation (short and clear):**  
- `student` → stores basic info.  
- `marks` → inherits from `student` and adds subject marks.  
- `result` → inherits from `marks`, calculates total and average.  

This is the clean, straightforward way to demonstrate **multilevel inheritance**.

