```cpp
#include <iostream>
using namespace std;

class Academic {
    int marks[3];
public:
    void getAcademic() {
        cout << "Enter marks of 3 subjects: ";
        for (int i = 0; i < 3; i++) cin >> marks[i];
    }
    void showAcademic() {
        cout << "Marks: ";
        for (int i = 0; i < 3; i++) cout << marks[i] << " ";
        cout << endl;
    }
};

class Sports {
    string game;
    int score;
public:
    void getSports() {
        cout << "Enter game name and score: ";
        cin >> game >> score;
    }
    void showSports() {
        cout << "Game: " << game << " | Score: " << score << endl;
    }
};

class Student : public Academic, public Sports {
    string name;
    int roll;
public:
    void getData() {
        cout << "Enter name and roll: ";
        cin >> name >> roll;
        getAcademic();
        getSports();
    }
    void showData() {
        cout << "\n--- Student Report ---\n";
        cout << "Name: " << name << " | Roll: " << roll << endl;
        showAcademic();
        showSports();
    }
};

int main() {
    Student s;
    s.getData();
    s.showData();
    return 0;
}
```

✅ **Short, readable, and functional.**  
No constructors, no unnecessary arrays for subjects — just the core logic of **multiple inheritance** linking academics + sports → student.
